def _marcar_jefes_no_finales(apps, schema_editor):
    """En cadenas de doble control ya existentes, el paso del jefe no es final.

    Las solicitudes de descarga 'restringido' creadas antes de la cadena
    secuencial tienen un paso 'jefe' + un paso 'autorizador'. El nuevo
    resolver decide si finaliza por ``es_final``: hay que marcar el del jefe
    como no final para que no apruebe solo. Las de un solo paso siguen con
    ``es_final=True``.
    """
    AprobacionDescarga = apps.get_model('documentos', 'AprobacionDescarga')
    solicitudes_con_autorizador = list(
        AprobacionDescarga.objects
        .filter(rol_aprobador='autorizador')
        .values_list('solicitud_id', flat=True)
    )
    if solicitudes_con_autorizador:
        (AprobacionDescarga.objects
         .filter(solicitud_id__in=solicitudes_con_autorizador,
                 rol_aprobador='jefe')
         .update(es_final=False))


